#!/usr/bin/env bash
# E12-S3: the git guards the pages rely on are installed and required.
#   Part 1  the rules, pinned whole, unit by unit: preflight offers pre-commit in its one install ask; the
#           build saves once on the default branch, then runs `pre-commit install`; Q12 is [BLOCK]; the
#           catch-up (/resume-it) and /retrofit-it switch the hooks on; every skill that saves for the user
#           runs the same hook check first and saves nothing when it prints HOOKS OFF.
#   Part 2  the hook check itself, run as written, in throwaway repos (no pre-commit needed)
#   Part 3  REAL behaviour: a throwaway repo with the scaffold's config, the build's step 41c run as
#           written, then a save on main and a save holding a planted key are refused and a clean save
#           on a branch goes through. Needs pre-commit and the network (it fetches the hooks): without
#           them it says SKIPPED loudly, and fails in CI, where the workflow installs pre-commit.
# Keys are built at run time; no secret is written in this repository.
set -uo pipefail
cd "$(dirname "$0")/.."
fail=0
ok()  { echo "ok    $*"; }
bad() { echo "FAIL  $*"; fail=1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT

GATE=$'[ ! -f "$(git rev-parse --show-toplevel)/.pre-commit-config.yaml" ] || grep -qs \'File generated by pre-commit\' "$(git rev-parse --git-path hooks/pre-commit)" ||'
CHECKS='the checks this project runs before every save (a scan for passwords and keys, and a stop on saving straight to the main copy) are switched off on this computer.'
M1="I haven't saved anything: $CHECKS Run /resume-it to switch them on."
ON="I switched on the checks your project runs before every save: a scan for passwords and keys, and a stop on saving straight to the main copy."

# --- Part 1: the rules, pinned whole --------------------------------------------------------------
# has FILE TEXT: TEXT appears in FILE with runs of white space (line wraps included) read as one space
has() { python3 - "$1" "$2" <<'PY'
import re, sys
flat = lambda s: re.sub(r"\s+", " ", s).strip()
sys.exit(0 if flat(sys.argv[2]) in flat(open(sys.argv[1], encoding="utf-8").read()) else 1)
PY
}
pin() { if has "$1" "$2"; then ok "$1 pins: ${3:-${2:0:70}}"; else bad "$1 lacks: ${3:-${2:0:90}}"; fi; }

MK=.claude/commands/make-it.md; PR=.claude/make-it/references/prerequisites.md
BS=.claude/make-it/references/build-standards.md; GO=.claude/make-it/references/git-operations.md
RS=.claude/commands/resume-it.md; RF=.claude/commands/retrofit-it.md
WR=.claude/commands/wrap-it.md; TR=.claude/commands/try-it.md; AR=.claude/commands/argo-it.md; FX=.claude/commands/fix-it.md
SC=.claude/make-it/scaffolds/fastapi-nextjs

# step 1: preflight checks for pre-commit and offers it in its one install ask (a pick, never silently)
pin "$MK" 'pre-commit --version 2>/dev/null   # runs the project'"'"'s checks before every save (prerequisites.md #6)' "preflight checks pre-commit"
pin "$PR" '### 6. pre-commit

**Why needed:** Runs the project'"'"'s checks before every save: gitleaks'"'"' scan for passwords and keys, and `no-commit-to-branch`, which stops a save straight to `main`. /make-it switches them on in every build (check Q12), and the skills that save for the user save nothing while they are off.
**How to check:** `pre-commit --version 2>/dev/null`
**What to tell the user it is:** "pre-commit -- runs your project'"'"'s checks before every save: a scan for passwords and keys, and a stop on saving straight to the main copy"
**If missing:** it is a Quick Fix, offered in preflight'"'"'s one install ask with the other missing tools (a pick: install it, walk them through it, or their company'"'"'s way), never installed without it.
- macOS: `brew install pre-commit`
- Windows: `py -m pip install --user pre-commit`
- Linux: `pipx install pre-commit` or `python3 -m pip install --user pre-commit`' "prerequisites #6 pre-commit"
pin "$PR" '- pre-commit installed? `pre-commit --version 2>/dev/null`' "the instant checks list pre-commit"
pin "$PR" '- Examples: Docker, GitHub CLI, VS Code, pre-commit' "pre-commit is a quick fix"

# step 2: the build saves once on the default branch, then switches the hooks on; Q12 is [BLOCK]
pin "$MK" 'The first save, and the switch that turns these hooks on (`pre-commit install`), are step 41c.' "step b points at 41c"
pin "$MK" '41c. **Save the build, then switch on the checks before every save (silent -- checks Q12, VC02).** The first save goes on the default branch while the hooks are still off, because the `no-commit-to-branch` hook refuses every save there -- the same order as /resume-it'"'"'s Desktop hand-off (step 0a). Before it, run `git status --short` and check that nothing secret-looking is about to be saved (never save a `.env` or key file; the scaffold'"'"'s `.gitignore` leaves them out). Then, in the project:

```bash
git add -A && git commit -q -m "Initial build" && pre-commit install >/dev/null &&
  grep -qs '"'"'File generated by pre-commit'"'"' "$(git rev-parse --git-path hooks/pre-commit)" && echo "HOOKS ON"
```

It must print `HOOKS ON` (Q12 is [BLOCK]); every later save runs the hooks. If it doesn'"'"'t, fix the cause and run it again -- a save that failed because git doesn'"'"'t know the user'"'"'s name and email: ask for them; `pre-commit` missing: preflight'"'"'s install ask for it. If the hooks still can'"'"'t be switched on (another tool already manages this project'"'"'s git hooks, for example), stop before /try-it and tell the user: "I couldn'"'"'t switch on the checks your project runs before every save (a scan for passwords and keys, and a stop on saving straight to the main copy), so I'"'"'ve stopped before showing you the app. [the reason, in plain words]"' "build step 41c"
pin "$BS" '**Q12** [Tier 0] [BLOCK] **Pre-commit hooks installed locally** -- When `.pre-commit-config.yaml` exists, the file git runs before each commit (`git rev-parse --git-path hooks/pre-commit`) exists and is pre-commit'"'"'s own: it holds `File generated by pre-commit`. /make-it runs `pre-commit install` right after the build'"'"'s first save on the default branch (build-verify step 41c), so in its first build-verify the check is made there, not in Part A. /resume-it'"'"'s catch-up and /retrofit-it switch it on when it is off (one plain line), asking preflight'"'"'s install pick for `pre-commit` first when it is missing. /wrap-it, /try-it, /argo-it, /fix-it, /resume-it and /retrofit-it run the same check before every save they make for the user and save nothing while it fails (`git-operations.md`, Before any save). CI does not depend on pre-commit hooks.' "Q12 [BLOCK]"
if grep -q 'Q12\*\* \[Tier 0\] \[WARN\]' "$BS"; then bad "Q12 is still [WARN]"; else ok "Q12 is no longer [WARN]"; fi
if grep -qiE 'where (it is |pre-commit is )?installed' "$BS" "$GO"; then bad "a 'where installed' escape is in the rules"; else ok "no 'where installed' escape in the rules"; fi
pin "$BS" 'The file extends gitleaks'"'"' default rules (`[extend]` with `useDefault = true`): a config that only lists allowlists has no rules, and gitleaks finds nothing.' "Q08 requires the default rules"

# the shared rule, and the check every save runs
pin "$GO" '### Before any save

A save a skill makes for the user never goes ahead with the project'"'"'s hooks switched off. Before it, run:

```bash
'"$GATE"' echo "HOOKS OFF"
```

It prints `HOOKS OFF` when the project has a `.pre-commit-config.yaml` but git has no pre-commit hook to run (check Q12). Then nothing is saved, and the user hears: "'"$M1"'" A project with no `.pre-commit-config.yaml` saves as before. Never get past it with `--no-verify`. The build'"'"'s first save (/make-it step 41c) and /resume-it'"'"'s Desktop hand-off come before the hooks are switched on, by design: they are the save `pre-commit install` follows.' "git-operations: Before any save"
pin "$GO" 'make-it'"'"'s installers add a Claude Code hook that refuses `git push --force`, `-f`, `--mirror` and `+refspec` pushes (`~/.claude/make-it/hooks/no-force-push.sh`) and lets `--force-with-lease` through.' "git-operations: the shipped hook"

# step 3: the catch-up and /retrofit-it switch the hooks on
pin "$RS" '- **Hooks on (Q12):** when `.pre-commit-config.yaml` exists and the hook check (`git-operations.md`, Before any save) prints `HOOKS OFF`: if `pre-commit` is installed, run `pre-commit install` now -- routine, no ask -- and say one line: "'"$ON"'" If `pre-commit` isn'"'"'t installed, ask preflight'"'"'s install pick for it (`make-it.md` preflight, the one ask for missing tools), then switch the hooks on the same way. If `pre-commit install` fails, say why in plain words (another tool already manages this project'"'"'s git hooks, for example) and that the checks stay off. Q12 never goes in the gaps list or its ask.' "resume-it catch-up Q12"
pin "$RS" 'Before `build-verify`'"'"'s step 41c (the first save on the default branch, then `pre-commit install`), do step a'"'"'s `.gitignore` and `git status` secret check; feature work then goes on a branch.' "resume-it Desktop plan path follows 41c"
pin "$RF" '- **Q01-Q16**: Code quality (Q14, the dead-code upkeep reminder, is N/A right after a retrofit; Q12 is switched on the way /resume-it'"'"'s catch-up does it, with its one plain line)' "retrofit Verify Q12"
pin "$RF" '**Before the snapshot, the hooks (Q12):** when the app has its own repo and a `.pre-commit-config.yaml`, run the hook check (`git-operations.md`, Before any save). On `HOOKS OFF`, switch the hooks on the way /resume-it'"'"'s catch-up does (Q12: `pre-commit install` and its one plain line, preflight'"'"'s install pick first when `pre-commit` is missing), then run the check again. Still `HOOKS OFF`: stop here, before any change, and tell the user: "I haven'"'"'t changed or saved anything: '"$CHECKS"' [when `pre-commit install` failed: the reason, in plain words / otherwise: Run /retrofit-it again and pick Install when I ask about pre-commit.]" A folder that wasn'"'"'t under git yet gets the same step right after the snapshot, before Phase 5: its snapshot is its first save, the one `pre-commit install` follows (as in /make-it step 41c).' "retrofit snapshot Q12"

# step 5: every skill that saves for the user runs the check first and saves nothing on HOOKS OFF
pin "$WR" '- Before staging anything, run the hook check (`git-operations.md`, Before any save):
  `'"$GATE"' echo "HOOKS OFF"`. If it prints `HOOKS OFF`, save nothing and say, in place of the save line: "'"$M1"'" The rest of the wrap-up goes on.' "wrap-it save"
pin "$TR" '- Before that save, run the hook check (`git-operations.md`, Before any save): `'"$GATE"' echo "HOOKS OFF"`. If it prints `HOOKS OFF`, commit nothing, and when the app is presented say: "'"$M1"'"' "try-it save"
pin "$AR" '# The project'"'"'s checks before every save must be on: a .pre-commit-config.yaml and no pre-commit hook saves nothing
'"$GATE"' { echo "HOOKS OFF"; exit 3; }' "argo-it 5b step 4 block"
pin "$AR" '**If the block prints `HOOKS OFF`, stop here -- nothing was saved or sent.** The project has a `.pre-commit-config.yaml`, but git has no pre-commit hook to run (`git-operations.md`, Before any save). Tell the user: "I haven'"'"'t saved or sent anything: '"$CHECKS"' What to do next: run /resume-it to switch them on, then run /argo-it again."' "argo-it HOOKS OFF rule"
pin "$FX" '**Before any commit in Steps 7-9**, run the hook check (`git-operations.md`, Before any save): `'"$GATE"' echo "HOOKS OFF"`. If it prints `HOOKS OFF`, commit nothing: the fixes stay in the files, unsaved, and the report opens with: "'"$M1"'"' "fix-it saves"
pin "$RS" 'Before that commit, run the hook check (`git-operations.md`, Before any save): `'"$GATE"' echo "HOOKS OFF"`. If it prints `HOOKS OFF` (the catch-up couldn'"'"'t switch the hooks on, or the user turned down installing pre-commit), commit nothing and say: "I haven'"'"'t saved anything: '"$CHECKS"' Say '"'"'switch on the save checks'"'"' and I'"'"'ll set them up."' "resume-it save"
# the scaffold: hooks that can run on any machine, and gitleaks with its rules
grep -q '^default_language_version:' "$SC/.pre-commit-config.yaml" && bad "the scaffold's hooks still need python3.12 on the user's machine" || ok "the scaffold's hooks run with any python3"
grep -q 'no-commit-to-branch' "$SC/.pre-commit-config.yaml" && grep -q 'id: gitleaks' "$SC/.pre-commit-config.yaml" && ok "the scaffold's config has no-commit-to-branch and gitleaks" || bad "the scaffold's config lost a guard"
python3 -c 'import sys,tomllib; d=tomllib.load(open(sys.argv[1],"rb")); sys.exit(0 if d.get("extend",{}).get("useDefault") is True else 1)' "$SC/.gitleaks.toml" 2>/dev/null \
  && ok "the scaffold's .gitleaks.toml keeps gitleaks' default rules" || bad "the scaffold's .gitleaks.toml has no rules of its own and doesn't extend the defaults"
# no skill gets past a hook
if grep -nE -- 'git (commit|push|merge|rebase|am)[^`]*--no-verify' .claude/commands/*.md .claude/make-it/references/*.md >/dev/null; then bad "a skill runs git with --no-verify"; else ok "no skill runs git with --no-verify"; fi

# --- Part 2: the hook check, run as written -----------------------------------------------------------
gate_line=$(python3 - "$GO" <<'PY'
import re, sys
t = open(sys.argv[1], encoding="utf-8").read()
m = re.search(r"### Before any save.*?```bash\n(.*?)\n```", t, re.S)
print(m.group(1) if m else "")
PY
)
if [ -z "$gate_line" ]; then bad "no hook check found in git-operations.md to run"; else
  git init -q -b main "$T/g" && cd "$T/g"
  [ -z "$(bash -c "$gate_line")" ] && ok "check: no .pre-commit-config.yaml -> nothing printed (saves as before)" || bad "check: a project without pre-commit was stopped"
  echo 'repos: []' > .pre-commit-config.yaml
  [ "$(bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: config and no hook -> HOOKS OFF" || bad "check: config and no hook was not stopped"
  mkdir -p sub && [ "$(cd sub && bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: run from a subfolder -> HOOKS OFF" || bad "check: missed from a subfolder"
  printf '#!/bin/sh\nexit 0\n' > .git/hooks/pre-commit; chmod +x .git/hooks/pre-commit
  [ "$(bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: some other pre-commit hook -> HOOKS OFF" || bad "check: a hook that isn't pre-commit's passed"
  printf '#!/usr/bin/env bash\n# File generated by pre-commit: https://pre-commit.com\n' > .git/hooks/pre-commit
  [ -z "$(bash -c "$gate_line")" ] && ok "check: pre-commit's hook -> nothing printed" || bad "check: pre-commit's own hook was refused"
  git config core.hooksPath "$T/elsewhere"
  [ "$(bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: core.hooksPath points away from the hook -> HOOKS OFF" || bad "check: core.hooksPath hid a missing hook"
  git config --unset core.hooksPath
  git worktree add -q "$T/g-wt" -b wt 2>/dev/null; cp .pre-commit-config.yaml "$T/g-wt/"
  [ -z "$(cd "$T/g-wt" && bash -c "$gate_line")" ] && ok "check: a worktree shares the repo's hook" || bad "check: a worktree was stopped though the hook is there"
  cd - >/dev/null
fi

# --- Part 3: real behaviour ---------------------------------------------------------------------------
skip3() { echo "SKIPPED  Part 3 (real commits with the scaffold's hooks): $1 -- NOT PROVEN on this machine"; [ -z "${CI:-}" ] || bad "Part 3 skipped in CI: $1"; }
block41=$(python3 - "$MK" <<'PY'
import re, sys
t = open(sys.argv[1], encoding="utf-8").read()
m = re.search(r"^41c\. .*?```bash\n(.*?)\n```", t, re.S | re.M)
print(m.group(1) if m else "")
PY
)
if ! command -v pre-commit >/dev/null 2>&1; then skip3 "pre-commit is not installed"
elif [ -z "$block41" ]; then bad "no step 41c block found in make-it.md to run"
else
  R="$T/app"; mkdir -p "$R" && cd "$R"
  git init -q -b main .
  cp "$OLDPWD/$SC/.pre-commit-config.yaml" "$OLDPWD/$SC/.gitleaks.toml" "$OLDPWD/$SC/pyproject.toml" "$OLDPWD/$SC/.gitignore" .
  echo '# app' > README.md
  git config user.name "git guards test"; git config user.email "guards@example.invalid"
  out=$(bash -c "$block41" 2>&1)
  if [ "$out" = "HOOKS ON" ] && grep -qs 'File generated by pre-commit' .git/hooks/pre-commit && [ "$(git rev-list --count HEAD)" = 1 ]; then
    ok "build step 41c, run as written: one save on main, then the pre-commit hook is in .git/hooks"
    if ! pre-commit install-hooks >"$T/ih" 2>&1; then skip3 "the hooks could not be fetched (no network?): $(tail -2 "$T/ih" | tr '\n' ' ')"
    else
      h0=$(git rev-parse HEAD)
      echo 'more' >> README.md; git add README.md
      if git commit -q -m "straight to main" >"$T/c1" 2>&1; then bad "a save straight to main went through"
      elif [ "$(git rev-parse HEAD)" = "$h0" ] && grep -q "commit to branch" "$T/c1"; then ok "a save straight to main is refused by no-commit-to-branch"
      else bad "a save to main failed, but not by no-commit-to-branch: $(tail -3 "$T/c1")"; fi
      git reset -q --hard
      git switch -q -c feature
      # a GitHub token shape, built here from random characters (never a literal in the repo)
      key=$(python3 -c 'import secrets,string; a=string.ascii_letters+string.digits; print("gh"+"p_"+"".join(secrets.choice(a) for _ in range(36)))')
      printf 'TOKEN = "%s"\n' "$key" > settings_local.txt; git add settings_local.txt
      h1=$(git rev-parse HEAD)
      if git commit -q -m "a key" >"$T/c2" 2>&1; then bad "a save holding a planted key went through"
      elif [ "$(git rev-parse HEAD)" = "$h1" ] && grep -qi "leaks found\|Detect hardcoded secrets.*Failed" "$T/c2"; then ok "a save holding a planted key is refused by gitleaks"
      else bad "a save holding a key failed, but not by gitleaks: $(tail -3 "$T/c2")"; fi
      grep -qF "$key" "$T/c2" && bad "the refusal printed the key" || ok "the refusal doesn't print the key"
      # control: the same key with the scaffold's old .gitleaks.toml (allowlists only, no rules) is NOT caught
      cp .gitleaks.toml "$T/gl.toml"; python3 - <<'PY'
import re; p=".gitleaks.toml"; s=open(p).read(); open(p,"w").write(re.sub(r"(?ms)^\[extend\].*?(?=^\[|\Z)", "", s))
PY
      git add .gitleaks.toml settings_local.txt
      if git commit -q -m "control" >"$T/c3" 2>&1; then ok "control: without [extend] useDefault, the same key gets through (the fix is what catches it)"; git reset -q --hard HEAD~1
      else bad "control: the key was refused even without the default rules -- the key test proves nothing about the fix: $(tail -2 "$T/c3")"; git reset -q; fi
      cp "$T/gl.toml" .gitleaks.toml; rm -f settings_local.txt; git checkout -q -- . 2>/dev/null
      echo 'hello' > notes.txt; git add notes.txt
      if git commit -q -m "a clean save on a branch" >"$T/c4" 2>&1; then ok "a clean save on a feature branch goes through the hooks"
      else bad "a clean save on a feature branch was refused: $(tail -5 "$T/c4")"; fi
    fi
  else bad "build step 41c did not switch the hooks on: $out"; fi
  cd - >/dev/null
fi

[ "$fail" = 0 ] && echo "PASS test-git-guards" || echo "FAILED test-git-guards"
exit $fail
